def _truncate_memory(text: str) -> tuple[str, str | None]:
    lines = text.splitlines(keepends=True)
    by_lines = "".join(lines[: MEMORY_LINES.value])
    by_bytes = text.encode()[: MEMORY_BYTES.value].decode("utf-8", errors="ignore")
