            end = line.find("-->")
            if end == -1:
                continue
            in_comment = False
            rest = line[end + 3 :]
            if rest.strip():
                out.append(rest)
            continue
        match = _FENCE.match(line)
        if match:
            if fence is None:
                fence = match.group(1)
            elif fence == match.group(1):
                fence = None
        if fence is None and not match and line.lstrip().startswith("<!--"):
            start = line.index("<!--")
            end = line.find("-->", start + 4)
            if end == -1:
                in_comment = True
                continue
            rest = line[end + 3 :]
            if rest.strip():
