    """
    Language-aware token estimation.
    English: ~4 chars per token. CJK: ~1.5 chars per token.
    """
    if not text:
        return 0

    english_chars = 0
    cjk_chars = 0
    other_chars = 0

    for ch in text:
        if is_cjk_char(ch):
            cjk_chars += 1
        elif ord(ch) < 128:
            english_chars += 1
        else:
            other_chars += 1

    tokens = (english_chars / 4) + (cjk_chars / 1.5) + (other_chars / 3)
    return int(tokens)


